/// <summary>
/// TelemetrySalesOrderConfirm class extending methods of METTelemetryBase class
/// </summary>
final class METTelemetrySalesOrderConfirm extends METTelemetryBase
{
    private SalesTable salesTable;
    private str error;
}

Method.Source:
void new( SalesTable _salesTable,  str _error)
{
    super();
    salesTable = _salesTable;
    this.addBaseProperty(METApplicationInsightsEventProperties::SalesId, salesTable.SalesId);
    this.addBaseProperty(METApplicationInsightsEventProperties::CustAccount, salesTable.CustAccount);
    this.addBaseProperty(METApplicationInsightsEventProperties::SalesStatus, strFmt("%1", salesTable.SalesStatus));
    this.addBaseProperty(METApplicationInsightsEventProperties::DeliveryDate, DateTimeUtil::toStr(salesTable.DeliveryDate));

    this.error = _error;
}

protected boolean shouldLogEvent()
{
    if(!this.error && telemetryLoggingParams.SeverityLevel > METTelemetrySeverityLevel::Information)
    {
        return false;
    }

    return true;
}

protected void populateProperties()
{
    // Setting elapsed milliseconds in the concrete implementation so that the implementer can decide what is the right way to get elapsed time.
    this.setElapsedMilliseconds();
}
